#!/usr/bin/env bash
# Проба registry-mirror базовых образов (Nexus :8083) перед сборкой образа.
#
# ЗАЧЕМ (CIM-02, хвост CIM-01). У остальных зеркал откат явный: use-nexus.sh
# проверяет живость Nexus и при отказе собирает напрямую, а gradle-retry.sh /
# compose-build-retry.sh при неудаче переигрывают сборку БЕЗ зеркала. У
# registry-mirror такого не было: он настроен в daemon.json РАННЕРА (вне репо,
# без проверки и фолбэка), и когда порт :8083 не был проброшен, все сборки
# образов легли на несколько часов вместо деградации к прямой тяге из Docker Hub
# (CIM-01, 2026-08-01). Скрипт при этом считал Nexus живым — он и был жив, просто
# зеркало образов слушало на другом, непроброшенном порту.
#
# ЧТО ДЕЛАЕТ. Docker Engine 29.x при недоступном registry-mirror сам откатывается
# на upstream (registry-1.docker.io) для docker.io-образов — то есть на текущем
# движке registry-mirror уже НЕ единая точка отказа сборки. Но этот откат немой:
# в логе он неотличим от «образа не существует», и именно эта немота стоила нам
# многочасовой слепой диагностики. Скрипт делает откат НАБЛЮДАЕМЫМ — одной
# строкой в логе видно, живо зеркало или пул пойдёт напрямую. Он ничего не чинит
# и не роняет: сборку не останавливает никогда (мёртвое зеркало — это ворнинг, а
# не ошибка), общий daemon.json раннера не трогает (его правка на лету гонялась
# бы с параллельными сборками соседних проектов на том же хосте).
#
# ПОЧЕМУ НЕ ПРАВИМ daemon.json НА ЛЕТУ. Раннер общий (Shuttle/Hound/aida-root/
# LORE). registry-mirror — глобальная настройка демона; снимать её посреди чужих
# сборок и перезагружать docker — вносить отказ вместо того, чтобы его убрать.
# Опора на штатный upstream-фолбэк движка + громкий ворнинг безопаснее и
# достаточна.
set -uo pipefail

MIRROR_HOST="${DOCKER_REGISTRY_MIRROR:-192.168.3.131:8083}"
PROBE_URL="http://${MIRROR_HOST}/v2/"

# 401/200 = реестр жив (401 — нормальный auth-challenge Docker-реестра, см.
# CIM-01). Пустой/000 или connection refused = зеркало не отвечает.
# -w '%{http_code}' сам печатает 000 при обрыве/refused, поэтому || не нужен —
# иначе к 000 добавился бы второй 000. Пустая строка (теоретическая) → 000.
code="$(curl -s --noproxy '*' -o /dev/null -m 8 -w '%{http_code}' "$PROBE_URL" 2>/dev/null)"
code="${code:-000}"

case "$code" in
  200|401)
    echo "::notice::registry-mirror $MIRROR_HOST жив (HTTP $code) — базовые образы идут через зеркало"
    ;;
  *)
    echo "::warning::registry-mirror $MIRROR_HOST не отвечает (HTTP $code) — базовые образы Docker Hub пойдут напрямую (upstream-фолбэк движка). Сборка не падает, но идёт медленнее и без кэша LAN. Если сборка образа всё же упадёт на 'FROM'/pull — причина здесь, а не в коде."
    ;;
esac

exit 0
